306	      AdminconfigrationID: props.AdminConfigrationListID,
307	      AdminConfigrationListID: props.AdminConfigrationListID,
308	      dropdownvalue: 'Component Portfolio'
309	    }),
310	    [props]
311	  );
312	
313	  return (
314	    <HashRouter>
315	      <SpaNavigationInterceptor />
316	      {/* hhhh-spa-webpart: Style.css body rules are compiled to this selector for SPFx */}
317	      <div className={`hhhh-spa-webpart ${styles.hhhhSpaShell}`} style={{ flexDirection: 'column' }}>
318	        <div style={{ flex: '0 0 auto', width: '100%' }}>
319	          <SpaTopNavigation siteUrl={props.siteUrl} context={props.Context} />
