import * as React from 'react';
import { HashRouter, useHistory, useLocation } from 'react-router-dom';
import { IHhhhSpaProps } from './IHhhhSpaProps';
import SpaLeftNavigation from './SpaLeftNavigation';
import SpaBreadcrumb from './SpaBreadcrumb';
import SpaNavigationInterceptor from './SpaNavigationInterceptor';
import SpaTopNavigation from './SpaTopNavigation';
import FeatureKeepAlive from './FeatureKeepAlive';
import SpaErrorBoundary from './SpaErrorBoundary';
import styles from './HhhhSpa.module.scss';
import PageSkeleton from '../common/PageSkeleton';
import { setActiveScope, wasScopeAborted, clearScopeAborted } from '@hochhuth-consulting/hhhh-shared-ui/HHHH-SP-Code/services/requestScope';

/**
 * Phase-2: shell lazy-loads feature entries only (UAT-style boundaries).
 * Page business logic stays under src/pages — features are thin wrappers.
 * Keep-alive + NavLinks / search sync unchanged.
 */
const TeamPortfolioFeature = React.lazy(
  () => import('../features/teamPortfolio/TeamPortfolioFeature')
);
const ProjectOverviewFeature = React.lazy(
  () => import('../features/projectOverview/ProjectOverviewFeature')
);
const CreateTaskFeature = React.lazy(
  () => import('../features/createTask/CreateTaskFeature')
);
const PortfolioProfileFeature = React.lazy(
  () => import('../features/portfolioProfile/PortfolioProfileFeature')
);
const TaskProfileFeature = React.lazy(
  () => import('../features/taskProfile/TaskProfileFeature')
);
const PxcProfileFeature = React.lazy(
  () => import('../features/pxcProfile/PxcProfileFeature')
);
const StaticDashboardFeature = React.lazy(
  () => import('../features/staticDashboard/StaticDashboardFeature')
);

function SuspensePage(props: {
  children: React.ReactNode;
  variant?: Parameters<typeof PageSkeleton>[0]['variant'];
  label?: string;
}): React.ReactElement {
  return (
    <SpaErrorBoundary label={props.label || props.variant || 'page'}>
      <React.Suspense fallback={<PageSkeleton variant={props.variant || 'default'} />}>
        {props.children}
      </React.Suspense>
    </SpaErrorBoundary>
  );
}

function useSearchKey(): string {
  const [searchKey, setSearchKey] = React.useState(() => window.location.search || '');

  React.useEffect(() => {
    const onChange = (): void => {
      setSearchKey(window.location.search || '');
    };
    window.addEventListener('popstate', onChange);
    window.addEventListener('hashchange', onChange);
    window.addEventListener('spa-search-change', onChange);
    return () => {
      window.removeEventListener('popstate', onChange);
      window.removeEventListener('hashchange', onChange);
      window.removeEventListener('spa-search-change', onChange);
    };
  }, []);

  return searchKey;
}

/**
 * UAT-style outlet: landing tools stay mounted (hide/show).
 * Detail profiles remount when query params change so legacy search readers work.
 */
function FeatureOutlet(props: { pageProps: any }): React.ReactElement {
  const { pageProps } = props;

  // Prefetch profile chunks while landing tools are open so the first
  // Team-Portfolio → Profile click does not flash Suspense PageSkeleton.
  React.useEffect(() => {
    void import('../features/portfolioProfile/PortfolioProfileFeature');
    void import('../features/taskProfile/TaskProfileFeature');
    void import('../features/pxcProfile/PxcProfileFeature');
  }, []);
  const location = useLocation();
  const history = useHistory();
  const searchKey = useSearchKey();
  const pathname = location.pathname || '';

  // Keep last profile remount key so clearing ?taskId on leave does not remount with nulls
  const portfolioKeyRef = React.useRef('portfolio-profile');
  const taskKeyRef = React.useRef('task-profile');
  const pxcKeyRef = React.useRef('pxc-profile');

  React.useEffect(() => {
    if (pathname === '/' || pathname === '') {
      history.replace('/team-portfolio');
    }
  }, [pathname, history]);

  const isTeamPortfolio = pathname.indexOf('/team-portfolio') === 0;
  const isProjectOverview = pathname.indexOf('/project-overview') === 0;
  const isCreateTask = pathname.indexOf('/create-task') === 0;
  const isPortfolioProfile = pathname.indexOf('/portfolio-profile') === 0;
  const isTaskProfile = pathname.indexOf('/task-profile') === 0;
  const isPxcProfile = pathname.indexOf('/pxc-profile') === 0;
  const isOmt = pathname.indexOf('/omt') === 0;

  React.useEffect(() => {
    if (isOmt) {
      document.title = "Operational Management Tool";
    } else if (isTeamPortfolio || isProjectOverview || isCreateTask) {
      document.title = "Task Management";
    }
  }, [isTeamPortfolio, isProjectOverview, isCreateTask, isOmt]);

  /**
   * List tools never set document.title themselves. Hierarchical profiles do
   * (`C246-…`, `PX123-…`), and keep-alive leaves those pages mounted, so the
   * tab title stuck after leaving for Create Task / OMT. Restore list titles
   * here; leave profile routes to the item loaders so PXC/portfolio/task titles
   * stay `{ID}-{Title}`.
   */
  React.useEffect(() => {
    if (isCreateTask) {
      document.title = 'Create Task';
      return;
    }
    if (isOmt) {
      document.title = 'OMT';
      return;
    }
    if (isTeamPortfolio) {
      document.title = 'Team Portfolio';
      return;
    }
    if (isProjectOverview) {
      document.title = 'PXC Management Overview';
    }
  }, [isCreateTask, isOmt, isTeamPortfolio, isProjectOverview]);

  /**
   * Team Portfolio (and profiles) write Portfolio Type color onto document
   * `--SiteColor`. Keep-alive leaves that value in place, so Project Overview /
   * Create Task / OMT incorrectly stayed Service-green. Restore the default
   * site blue for those non-portfolio tabs only — Tailwind `var(--SiteColor)`
   * consumers pick it up with no business-logic changes.
   */
  React.useEffect(() => {
    if (isProjectOverview || isCreateTask || isOmt) {
      document.documentElement.style.setProperty('--SiteColor', '#2F5596');
    }
  }, [isProjectOverview, isCreateTask, isOmt]);

  /**
   * Item ids are mirrored into window.location.search by navigateSpa (legacy
   * readers). HashRouter's location.search is often empty while the real URL
   * is `workbench.aspx?ProjectId=12920#/pxc-profile`. Prefer window search so
   * each profile item gets its own cancellable scope — otherwise every PXC
   * shares `pxc-profile`, setActiveScope no-ops, and Documents batches stack.
   */
  const hashQuery = React.useMemo(() => {
    if (searchKey && searchKey.length > 1) {
      return searchKey;
    }
    if (location.search && location.search.length > 1) {
      return location.search;
    }
    if (window.location.hash.indexOf('?') !== -1) {
      return window.location.hash.slice(window.location.hash.indexOf('?'));
    }
    return '';
  }, [location.search, location.pathname, searchKey]);

  // Publish the active route to the request layer. Leaving a profile aborts
  // every SharePoint call it still had in flight (see requestScope).
  const scopeId = React.useMemo(() => {
    if (isTeamPortfolio) return 'team-portfolio';
    if (isProjectOverview) return 'project-overview';
    if (isCreateTask) return 'create-task';
    if (isOmt) return 'omt';

    if (isPortfolioProfile) return `portfolio-profile${hashQuery}`;
    if (isTaskProfile) return `task-profile${hashQuery}`;
    if (isPxcProfile) return `pxc-profile${hashQuery}`;
    return 'global';
  }, [
    isTeamPortfolio, isProjectOverview, isCreateTask, isOmt,
    isPortfolioProfile, isTaskProfile, isPxcProfile, hashQuery
  ]);

  // Set during render, not in an effect: child effects (which start the data
  // loads) run before parent effects, so an effect here would file a profile's
  // first requests under the previous route and they'd never be aborted.
  // setActiveScope is idempotent and no-ops when the scope is unchanged.
  setActiveScope(scopeId);

  /**
   * Returning to a profile whose load we cancelled: features stay mounted, so
   * its effects will not re-run by themselves and it would render empty
   * forever. Bumping the remount key gives it a clean mount and a fresh load.
   */
  const [reloadNonce, setReloadNonce] = React.useState({ portfolio: 0, task: 0, pxc: 0 });
  const isProfileRoute = isPortfolioProfile || isTaskProfile || isPxcProfile;
  React.useEffect(() => {
    if (!isProfileRoute || !wasScopeAborted(scopeId)) {
      return;
    }
    clearScopeAborted(scopeId);
    /**
     * PXC used to skip the remount whenever an in-memory seed existed, on the
     * grounds that restoring the hidden instance was enough. It is not: we only
     * reach this branch because the scope WAS aborted, so that instance had its
     * in-flight requests cancelled part-way through. The seed carries the header
     * row alone — deliverables, documents and tasks were left unloaded — so
     * reopening the same PXC showed a blank profile.
     *
     * Portfolio Profile and Task Profile have always remounted here and reload
     * cleanly, so PXC takes the same path rather than a special case.
     */
    const which = isPortfolioProfile ? 'portfolio' : isTaskProfile ? 'task' : 'pxc';
    setReloadNonce((n) => ({ ...n, [which]: n[which] + 1 }));
  }, [isProfileRoute, isPortfolioProfile, isTaskProfile, isPxcProfile, scopeId]);

  if (isPortfolioProfile && searchKey && searchKey.indexOf('taskId=') !== -1) {
    portfolioKeyRef.current = `portfolio-profile-${searchKey}`;
  }
  if (isTaskProfile && searchKey && searchKey.indexOf('taskId=') !== -1) {
    taskKeyRef.current = `task-profile-${searchKey}`;
  }
  if (isPxcProfile && searchKey && searchKey.indexOf('ProjectId=') !== -1) {
    pxcKeyRef.current = `pxc-profile-${searchKey}`;
  }

  const portfolioKey = `${portfolioKeyRef.current}-${reloadNonce.portfolio}`;
  const taskKey = `${taskKeyRef.current}-${reloadNonce.task}`;
  const pxcKey = `${pxcKeyRef.current}-${reloadNonce.pxc}`;

  return (
    <>
      <FeatureKeepAlive active={isTeamPortfolio} featureId="team-portfolio">
        <SuspensePage variant="team-portfolio" label="Team Portfolio">
          <TeamPortfolioFeature pageProps={pageProps} />
        </SuspensePage>
      </FeatureKeepAlive>

      <FeatureKeepAlive active={isProjectOverview} featureId="project-overview">
        <SuspensePage variant="project-overview" label="Project Overview">
          <ProjectOverviewFeature pageProps={pageProps} />
        </SuspensePage>
      </FeatureKeepAlive>

      <FeatureKeepAlive active={isCreateTask} featureId="create-task" keepAlive={false}>
        <SuspensePage variant="create-task" label="Create Task">
          <CreateTaskFeature pageProps={pageProps} />
        </SuspensePage>
      </FeatureKeepAlive>

      <FeatureKeepAlive active={isPortfolioProfile} featureId="portfolio-profile">
        <SuspensePage label="Portfolio Profile">
          <PortfolioProfileFeature
            pageProps={pageProps}
            remountKey={portfolioKey}
          />
        </SuspensePage>
      </FeatureKeepAlive>

      <FeatureKeepAlive active={isTaskProfile} featureId="task-profile">
        <SuspensePage label="Task Profile">
          <TaskProfileFeature
            pageProps={pageProps}
            remountKey={taskKey}
          />
        </SuspensePage>
      </FeatureKeepAlive>

      <FeatureKeepAlive active={isPxcProfile} featureId="pxc-profile">
        <SuspensePage label="PXC Profile">
          <PxcProfileFeature
            pageProps={pageProps}
            remountKey={pxcKey}
          />
        </SuspensePage>
      </FeatureKeepAlive>

      <FeatureKeepAlive active={isOmt} featureId="omt">
        <SuspensePage variant="omt" label="OMT">
          <StaticDashboardFeature pageProps={pageProps} />
        </SuspensePage>
      </FeatureKeepAlive>
    </>
  );
}

/**
 * One SPA web part shell — HashRouter + keep-alive + feature lazy entries.
 */
export default function HhhhSpaApp(props: IHhhhSpaProps): React.ReactElement<IHhhhSpaProps> {
  const pageProps = React.useMemo(
    () => ({
      ...props,
      AdminconfigrationID: props.AdminConfigrationListID,
      AdminConfigrationListID: props.AdminConfigrationListID,
      dropdownvalue: 'Component Portfolio'
    }),
    [props]
  );

  return (
    <HashRouter>
      <SpaNavigationInterceptor />
      {/* hhhh-spa-webpart: Style.css body rules are compiled to this selector for SPFx */}
      <div className={`hhhh-spa-webpart ${styles.hhhhSpaShell}`} style={{ flexDirection: 'column' }}>
        <div style={{ flex: '0 0 auto', width: '100%' }}>
          <SpaTopNavigation siteUrl={props.siteUrl} context={props.Context} />
        </div>
        <div style={{ display: 'flex', flex: '1 1 auto', minHeight: 0, minWidth: 0, width: '100%' }}>
          <SpaLeftNavigation>
            <SpaBreadcrumb />
            <FeatureOutlet pageProps={pageProps} />
          </SpaLeftNavigation>
        </div>
      </div>
    </HashRouter>
  );
}

