import * as React from 'react';
import * as ReactDOM from 'react-dom';
import { MsalProvider } from '@azure/msal-react';
import { FluentProvider, webLightTheme } from '@fluentui/react-components';
import $ from 'jquery';
import { Buffer } from 'buffer';
import { msalInstance, ensureMsalInitialized } from './auth/msalConfig';
import {
  installSharePointFetchProxy,
  installSharePointJqueryProxy
} from './auth/sharePointProxy';
import { installSharePointImageAuth } from './auth/spAuthenticatedImage';
import AuthGate from './AuthGate';
import App from './App';

import './assets/tailwind.css';
import './assets/site_color.css';
import './assets/global-style.css';
import './app-host.css';

// Legacy SPFx pages expect global jQuery (`$.each`, `$('#...')`).
(window as any).$ = $;
(window as any).jQuery = $;
(window as any).Buffer = (window as any).Buffer || Buffer;
(window as any).global = (window as any).global || window;

async function bootstrap(): Promise<void> {
  installSharePointFetchProxy();
  // Timesheet / legacy popups still use $.ajax to absolute SPO URLs —
  // same /__sp rewrite + Bearer as fetch, or entries stay empty on localhost.
  installSharePointJqueryProxy($);
  // Portrait / icon <img> and Fluent Avatar need Bearer too — browser img
  // GETs cannot send Authorization, so rewrite via authenticated blob URLs.
  installSharePointImageAuth();
  await ensureMsalInitialized();

  try {
    await msalInstance.handleRedirectPromise();
  } catch (e) {
    console.warn('MSAL redirect handling failed', e);
  }

  const root = document.getElementById('root');
  if (!root) {
    throw new Error('#root element missing');
  }

  ReactDOM.render(
    <MsalProvider instance={msalInstance}>
      <FluentProvider theme={webLightTheme} style={{ minHeight: '100%' }}>
        <AuthGate>
          <App />
        </AuthGate>
      </FluentProvider>
    </MsalProvider>,
    root
  );
}

bootstrap().catch((err) => {
  console.error(err);
  const root = document.getElementById('root');
  if (root) {
    root.innerHTML = `<pre style="padding:24px;color:#a4262c">${String(err)}</pre>`;
  }
});

