import * as React from 'react';
import { getAllListIds } from '@hochhuth-consulting/hhhh-shared-ui/HHHH-SP-Code/services/globalCommon';
import { installFlyoutZKeeper } from '@hochhuth-consulting/hhhh-shared-ui/HHHH-Tasks/modals/flyoutZKeeper';
import HhhhSpaApp from './spa/HhhhSpa';
import type { IHhhhSpaProps } from './spa/IHhhhSpaProps';
import { createSpfxContextShim, hydrateCurrentUserId } from './auth/createSpfxContext';
import { configurePnpWithMsal } from './auth/configurePnp';
import { spSiteUrl, getActiveAccount } from './auth/msalConfig';
import { devSuccess } from './common/Utils';
import PageSkeleton from './common/PageSkeleton';

const DEFAULT_LIST_IDS = {
  MasterTaskListID: 'ec34b38f-0669-480a-910c-f84e92e58adf',
  TaskUserListID: 'b318ba84-e21d-4876-8851-88b94b9dc300',
  SmartMetadataListID: '01a34938-8c7e-4ea6-a003-cee649e8c67a',
  SmartHelpListID: '9CF872FC-AFCD-42A5-87C0-AAB0C80C5457',
  SmartInformationListID: 'edf0a6fb-f80e-4772-ab1e-666af03f7ccd',
  DocumentsListID: 'd0f88b8f-d96d-4e12-b612-2706ba40fb08',
  TaskTimeSheetListID: '464fb776-e4b3-404c-8261-7d3c50ff343f',
  TaskTypeID: '21b55c7b-5748-483a-905a-62ef663972dc',
  PortFolioTypeID: 'c21ab0e4-4984-4ef7-81b5-805efaa3752e',
  AdminConfigrationListID: 'e968902a-3021-4af2-a30a-174ea95cf8fa',
  ColumnManagementListID: 'fb4b4ae0-fb2d-4623-bffd-a7172e12cd09',
  DeploymentTypeId: 'E8E5B5E8-05DB-4A3C-B96D-172CB3802B5A',
  SmalsusLeaveCalendar: '72aba576-5272-4e30-b332-25d7e594aaa4'
};

/**
 * Replaces HhhhSpaWebPart.render — same props / list-id resolution, MSAL context.
 */
export default function App(): React.ReactElement {
  const [spaProps, setSpaProps] = React.useState<IHhhhSpaProps | null>(null);
  const [error, setError] = React.useState<string | null>(null);

  React.useEffect(() => {
    configurePnpWithMsal();
    const stopFlyout = installFlyoutZKeeper();
    let cancelled = false;

    (async () => {
      try {
        const context = createSpfxContextShim(spSiteUrl);
        await hydrateCurrentUserId(context);

        let resolvedIds: any = {};
        try {
          const listIds = await getAllListIds(spSiteUrl);
          resolvedIds = listIds && listIds[0] ? listIds[0] : {};
          devSuccess('HHHH React ListIDs', listIds);
        } catch (e) {
          // defaults remain available
          console.warn('getAllListIds failed; using defaults', e);
        }

        const pick = (fallbackKey: keyof typeof DEFAULT_LIST_IDS): string => {
          return resolvedIds[fallbackKey] || DEFAULT_LIST_IDS[fallbackKey];
        };

        const account = getActiveAccount();
        const next: IHhhhSpaProps = {
          description: 'HHHH React App',
          isDarkTheme: false,
          environmentMessage: 'Standalone React + MSAL',
          hasTeamsContext: false,
          userDisplayName: account?.name || context.pageContext.user.displayName,
          Context: context,
          pageContext: context.pageContext,
          siteUrl: spSiteUrl,
          MasterTaskListID: pick('MasterTaskListID'),
          TaskUserListID: pick('TaskUserListID'),
          SmartMetadataListID: pick('SmartMetadataListID'),
          SmartHelpListID: pick('SmartHelpListID'),
          SmartInformationListID: pick('SmartInformationListID'),
          DocumentsListID: pick('DocumentsListID'),
          TaskTimeSheetListID: pick('TaskTimeSheetListID'),
          TaskTypeID: pick('TaskTypeID'),
          PortFolioTypeID: pick('PortFolioTypeID'),
          AdminConfigrationListID: pick('AdminConfigrationListID'),
          ColumnManagementListID: pick('ColumnManagementListID'),
          DeploymentTypeId: pick('DeploymentTypeId'),
          SmalsusLeaveCalendar: pick('SmalsusLeaveCalendar'),
          // SPFx property pane / manifest pass these as JSON strings ("true"),
          // not booleans — many screens call .toLowerCase() / JSON.parse on them.
          TimeEntry: 'true',
          SiteCompostion: 'true'
        };

        if (!cancelled) setSpaProps(next);
      } catch (e: any) {
        if (!cancelled) setError(e?.message || String(e));
      }
    })();

    return () => {
      cancelled = true;
      stopFlyout?.();
    };
  }, []);

  if (error) {
    return (
      <div style={{ padding: 32, fontFamily: 'Segoe UI, sans-serif', color: '#a4262c' }}>
        <h2>Failed to start HHHH app</h2>
        <pre>{error}</pre>
      </div>
    );
  }

  if (!spaProps) {
    return <PageSkeleton variant="default" />;
  }

  return <HhhhSpaApp {...spaProps} />;
}

